BEGIN;
CREATE SCHEMA IF NOT EXISTS cause;
SET LOCAL search_path TO cause, public;
CREATE TABLE IF NOT EXISTS cause_auth_bindings (binding_hash text PRIMARY KEY, epoch bigint NOT NULL DEFAULT 0 CHECK(epoch>=0), current_context_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cause_auth_transactions (state_hash text PRIMARY KEY, binding_hash text NOT NULL REFERENCES cause_auth_bindings(binding_hash), epoch bigint NOT NULL, intent text NOT NULL CHECK(intent IN ('continue','switch','reauth')), nonce_secret text, verifier_secret text, return_to text NOT NULL, require_fresh_auth boolean NOT NULL DEFAULT false, reauth_requested_at timestamptz, expected_subject text, status text NOT NULL CHECK(status IN ('pending','processing','succeeded','failed','expired','cancelled')), expires_at timestamptz NOT NULL, claim_hash text, processing_deadline timestamptz, failure_code text, result_context_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE cause_auth_transactions ADD COLUMN IF NOT EXISTS require_fresh_auth boolean NOT NULL DEFAULT false;
ALTER TABLE cause_auth_transactions ADD COLUMN IF NOT EXISTS reauth_requested_at timestamptz;
ALTER TABLE cause_auth_transactions ADD COLUMN IF NOT EXISTS expected_subject text;
ALTER TABLE cause_auth_transactions DROP CONSTRAINT IF EXISTS cause_auth_transactions_intent_check;
ALTER TABLE cause_auth_transactions ADD CONSTRAINT cause_auth_transactions_intent_check CHECK(intent IN ('continue','switch','reauth'));
CREATE INDEX IF NOT EXISTS cause_auth_transactions_binding_epoch ON cause_auth_transactions(binding_hash,epoch,status);
CREATE INDEX IF NOT EXISTS cause_auth_transactions_expiry ON cause_auth_transactions(expires_at);
CREATE TABLE IF NOT EXISTS cause_auth_contexts (context_id text PRIMARY KEY, binding_hash text NOT NULL REFERENCES cause_auth_bindings(binding_hash), app_session_ref text NOT NULL UNIQUE, proof_hash text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(binding_hash,context_id));
CREATE INDEX IF NOT EXISTS cause_auth_contexts_binding ON cause_auth_contexts(binding_hash,revoked_at);
ALTER TABLE auth_sessions ADD COLUMN IF NOT EXISTS session_policy_version integer NOT NULL DEFAULT 0;
ALTER TABLE auth_sessions ADD COLUMN IF NOT EXISTS persistence_mode text NOT NULL DEFAULT 'session';
ALTER TABLE auth_sessions ADD COLUMN IF NOT EXISTS issuer text;
ALTER TABLE auth_sessions ADD COLUMN IF NOT EXISTS issuer_sid text;
COMMIT;
